int kthFree(int* taken, int takenSize, int k) {
    int prev = 0, left = k;
    for (int i = 0; i < takenSize; i++) {
        int gap = taken[i] - prev - 1;
        if (gap >= left) return prev + left;
        left -= gap;
        prev = taken[i];
    }
    return prev + left;
}

