class Solution {
    public int kthFree(int[] taken, int k) {
        int lo = 0, hi = taken.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (taken[mid] - (mid + 1) < k) lo = mid + 1;
            else hi = mid;
        }
        return lo + k;
    }
}

